import hashlib


def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs, chosen deterministically from seed.

    The same (xs, seed) pair always yields the same element. No randomness is used.
    """
    digest = hashlib.sha256(str(seed).encode("ascii")).digest()
    index = int.from_bytes(digest, "big") % len(xs)
    return xs[index]


def test_pick_returns_member() -> None:
    xs = [3, 5, 7]
    for seed in range(20):
        assert pick(xs, seed) in xs


def test_pick_same_seed_same_element() -> None:
    xs = [10, 20, 30, 40]
    first = pick(xs, 42)
    for _ in range(5):
        assert pick(xs, 42) == first


def test_pick_singleton_list() -> None:
    for seed in range(-3, 4):
        assert pick([9], seed) == 9


def test_pick_negative_seed_is_member() -> None:
    xs = [1, 2, 3]
    assert pick(xs, -5) in xs


def test_pick_varies_across_seeds() -> None:
    xs = [1, 2, 3, 4]
    picked = {pick(xs, seed) for seed in range(200)}
    assert len(picked) > 1
